import{_ as r,o as a,c as e,a8 as t}from"./chunks/framework.BWjTbCIc.js";const u=JSON.parse('{"title":"维多利亚幼稚园（VEO） · 年份未注明 · 幼儿预备班 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"victoria-kindergarten","school_zh":"维多利亚幼稚园（VEO）","school_en":"Victoria Educational Organisation","grade":"pn","year":"unknown","year_label":"年份未注明","type":"interview","title":"维多利亚幼稚园（VEO） · 年份未注明 · 幼儿预备班 · 面试","anonymous":true,"source_ids":["INT-VEO-PN-FAMILY","INT-VEO-PN-R2","INT-VEO-PN-VIDEO"],"rounds":["unknown","r2","r1"]},"headers":[],"relativePath":"reports/victoria-kindergarten/pn/unknown-interview.md","filePath":"reports/victoria-kindergarten/pn/unknown-interview.md"}'),n={name:"reports/victoria-kindergarten/pn/unknown-interview.md"};function i(l,o,p,s,d,h){return a(),e("div",null,[...o[0]||(o[0]=[t('<h1 id="维多利亚幼稚园-veo-·-年份未注明-·-幼儿预备班-·-面试" tabindex="-1">维多利亚幼稚园（VEO） · 年份未注明 · 幼儿预备班 · 面试 <a class="header-anchor" href="#维多利亚幼稚园-veo-·-年份未注明-·-幼儿预备班-·-面试" aria-label="Permalink to &quot;维多利亚幼稚园（VEO） · 年份未注明 · 幼儿预备班 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/victoria-kindergarten">← 返回维多利亚幼稚园（VEO）资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-int-veo-pn-family" tabindex="-1">资料来源：维多利亚国际幼儿园-PN班.pdf <a class="header-anchor" href="#record-int-veo-pn-family" aria-label="Permalink to &quot;资料来源：维多利亚国际幼儿园-PN班.pdf {#record-int-veo-pn-family}&quot;">​</a></h2><p><strong>资料类型：</strong> 家长考后反馈</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>家长面谈：</strong> 中文、英语</p><p><strong>孩子的性格、语言与兴趣</strong></p><p>英文问答围绕以下内容展开：</p><ul><li>描述孩子的性格。</li><li>家中使用什么语言？</li><li>孩子最喜欢什么活动？</li><li>是否有阅读习惯，平时读哪些书？</li><li>是否参加过亲子游戏小组（playgroup）？</li><li>孩子的名字如何发音？</li></ul><p><strong>家庭活动与选校考虑</strong></p><p>中文问答包括日常亲子活动、孩子此前在北京就读的托班是否为双语教学、目前英语水平，以及选择维多利亚幼稚园的原因。</p><p><strong>下午班意向</strong></p><p>老师询问是否接受下午班。家长此次申请插班，当时上午班已经满额，家长表示可以接受下午班。</p></blockquote><blockquote><p><strong>幼儿互动：</strong> 英语</p><p><strong>玩具、图书与简单问答</strong></p><p>老师向孩子提供玩具和书籍，观察其兴趣，并以英语提问：</p><ul><li>“Can you introduce yourself to us?”（介绍自己。）</li><li>“What is your favorite color?”（最喜欢什么颜色？）</li><li>“How many round pieces are in your hand?”（手里有多少个圆形片？）</li></ul></blockquote><h2 id="record-int-veo-pn-r2" tabindex="-1">资料来源：维多利亚国际幼儿园-PN班.pdf <a class="header-anchor" href="#record-int-veo-pn-r2" aria-label="Permalink to &quot;资料来源：维多利亚国际幼儿园-PN班.pdf {#record-int-veo-pn-r2}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理的面试流程与题目</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>面试安排：</strong></p><p><strong>家长单独面谈</strong></p><p>第二轮只面试家长，全程约10分钟，由校长及一位老师参与。建议提前5至10分钟到校，接待人员核对学生身份后安排等候；面谈前填写申请表及问卷。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 中文／英语／粤语可选</p><p><strong>性格、经历与升学规划</strong></p><p>可选择中文、英语或粤语交流，问题包括：</p><ul><li>在家长眼中，孩子是什么样的？</li><li>孩子是否参加过playgroup？为什么选择该课程？</li><li>为什么选择VEO？</li><li>未来计划让孩子就读哪一类型的小学？</li></ul><p><strong>家长提问</strong></p><p>面谈中留有家长向学校提问的机会。</p></blockquote><h2 id="record-int-veo-pn-video" tabindex="-1">资料来源：维多利亚国际幼儿园-PN班.mp4 <a class="header-anchor" href="#record-int-veo-pn-video" aria-label="Permalink to &quot;资料来源：维多利亚国际幼儿园-PN班.mp4 {#record-int-veo-pn-video}&quot;">​</a></h2><p><strong>资料类型：</strong> 家长视频反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>小组活动：</strong> 中文／英语／粤语</p><h3 id="陪同与分组" tabindex="-1">陪同与分组 <a class="header-anchor" href="#陪同与分组" aria-label="Permalink to &quot;陪同与分组&quot;">​</a></h3><p>由一位家长陪同进入教室，约6-8名儿童一组。三位老师分别以中文、英语及粤语与儿童打招呼、一起玩玩具并温和提问。</p><h3 id="观察重点" tabindex="-1">观察重点 <a class="header-anchor" href="#观察重点" aria-label="Permalink to &quot;观察重点&quot;">​</a></h3><p>家长总结观察内容包括适应新环境、理解并回应指令、专注玩玩具，以及与其他儿童相处是否出现冲突。</p><h3 id="围圈律动与告别" tabindex="-1">围圈律动与告别 <a class="header-anchor" href="#围圈律动与告别" aria-label="Permalink to &quot;围圈律动与告别&quot;">​</a></h3><p>老师带领儿童围坐唱英文歌、做简单律动，观察模仿与参与；最后引导挥手说再见。</p></blockquote><h3 id="第二轮-·-原文明示-1" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示-1" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>家长面谈：</strong> 中文／英语</p><h3 id="第二轮参加者" tabindex="-1">第二轮参加者 <a class="header-anchor" href="#第二轮参加者" aria-label="Permalink to &quot;第二轮参加者&quot;">​</a></h3><p>这一轮主要面见家长，讲述者的经历为通常无需带孩子；由中文老师与外籍老师共同面谈。</p><h3 id="中文问题" tabindex="-1">中文问题 <a class="header-anchor" href="#中文问题" aria-label="Permalink to &quot;中文问题&quot;">​</a></h3><p>为何选择VEO？孩子的性格、优点与不足是什么？以前读过哪些学校或playgroup？平时有哪些亲子活动，家长如何分工？此次家长来面试时由谁照顾孩子？</p><h3 id="英文问题" tabindex="-1">英文问题 <a class="header-anchor" href="#英文问题" aria-label="Permalink to &quot;英文问题&quot;">​</a></h3><p>孩子上学持续哭闹时怎样处理？家庭主要使用什么语言？这两题要求用英语回答。</p></blockquote>',25)])])}const g=r(n,[["render",i]]);export{u as __pageData,g as default};
